"""Finish TB with adverse-event reasoning, follow-up and post-TB disease."""
from create_tuberculosis import rows,q,DX,TX,CD,LT,DR,AE
from qbank_authoring import ref,finalize
HE=ref('ATS/CDC/IDSA: Treatment of Drug-Susceptible Tuberculosis','https://pmc.ncbi.nlm.nih.gov/articles/PMC6590850/')
PT=ref('International Clinical Standards: Assessment, Management and Rehabilitation of Post-TB Lung Disease','https://theunion.org/sites/default/files/2021-10/Clinical%20standards%20for%20the%20assessment%2C%20management%20and%20rehabilitation%20of%20post-TB%20lung%20disease.pdf')
q('A patient on HRZE develops nausea and jaundice with ALT six times the upper limit of normal. What is the appropriate immediate principle?', 'Interrupt the potentially hepatotoxic agents and urgently assess drug-induced liver injury and other causes while planning safe TB treatment',[
 ('Continue unchanged because every ALT rise is expected','Symptoms and this enzyme elevation meet a concerning toxicity threshold.'),('Stop only ethambutol as the most likely hepatotoxic component','Isoniazid, rifampicin and pyrazinamide are the principal hepatotoxic first-line agents.'),('Add another hepatotoxic drug to maintain the same regimen','This does not address the acute injury.')],
 'Symptomatic liver injury requires action', '**Suspect treatment-related DILI at ALT at least three times normal with hepatitis symptoms, or at least five times without symptoms.**',['Assess bilirubin, coagulation and illness severity.','Investigate viral, biliary and other competing causes.'], '**Coordinate interruption, temporary coverage and later reintroduction with expertise.**',['The approach depends on disease severity and liver recovery.','Do not simply leave severe TB untreated for an undefined period.'],[['Symptomatic ALT threshold','At least 3 times upper limit'],['Asymptomatic threshold','At least 5 times upper limit'],['Key agents','H, R and Z']],[HE],style='clinical_scenario')
q('A patient beginning rifampicin asks about oral contraceptive reliability. What is the most important counseling point?', 'Rifampicin induces drug metabolism and can reduce hormonal contraceptive effectiveness, requiring an appropriate alternative strategy',[
 ('Rifampicin has no clinically relevant interactions','It is a major enzyme inducer.'),('Orange urine proves toxic liver injury','Orange-red body-fluid discoloration is expected and is not itself hepatitis.'),('Taking the contraceptive at a different clock time removes induction','Enzyme induction persists beyond the simultaneous dosing period.')],
 'Rifamycin interactions can be clinically decisive', '**Rifampicin can lower exposure to several coadministered medicines.**',['Review contraception, anticoagulants, transplant drugs and antiretrovirals.','Not every interaction is corrected by separating doses.'], '**Provide a practical medication and contraception plan.**',['Use a suitable method unaffected by the interaction according to local guidance.','Distinguish expected discoloration from jaundice or other adverse symptoms.'],[['Mechanism','Enzyme and transporter induction'],['Consequence','Reduced exposure to susceptible drugs'],['Counseling','Interaction review and alternative plan']],[AE],style='clinical_scenario')
q('A patient on pyrazinamide has elevated serum urate but no joint symptoms or other toxicity. What is the best interpretation?', 'Asymptomatic hyperuricemia is a recognized effect and does not by itself mandate stopping pyrazinamide',[
 ('It establishes acute gout','Gout requires a compatible clinical arthritis syndrome.'),('It proves treatment failure','Serum urate is not a marker of TB microbiological response.'),('It automatically requires permanent cessation of every TB drug','That response is disproportionate to the isolated finding.')],
 'Separate a common biochemical effect from clinically important toxicity', '**Pyrazinamide commonly raises urate.**',['Ask about joint pain and inflammatory arthritis.','Other toxicities, particularly liver injury, require separate assessment.'], '**Continue a clinically appropriate regimen unless there is a reason to change it.**',['Treat symptomatic complications when present.','Do not create an inadequate regimen in response to an isolated expected laboratory change.'],[['Isolated urate elevation','Often expected'],['Acute arthritis','Evaluate for gout and alternatives'],['Treatment change','Based on clinically relevant toxicity']],[AE],style='clinical_scenario')
q('A patient with pulmonary TB feels better after three treatment weeks and wants to stop. What is the best explanation for continuing the prescribed effective course?', 'Symptomatic improvement can precede eradication, and premature cessation raises relapse and resistance risks',[
 ('Clinical improvement means the initial diagnosis must have been incorrect','An effective regimen commonly improves symptoms.'),('Stopping now guarantees lifelong sterilizing immunity','It does not.'),('Only the first three weeks have antimicrobial activity','Later treatment contributes importantly to durable cure.')],
 'Early improvement is a treatment response, not proof of cure', '**Different bacillary populations and disease sites clear at different rates.**',['Validated regimens include an adequate duration of combination treatment.','Interruptions must be assessed rather than ignored.'], '**Use patient-centered adherence support.**',['Identify cost, adverse effects and practical barriers.','Provide clear follow-up and treatment-support arrangements rather than blame.'],[['Early response','Encouraging but not cure'],['Completion','Supports durable treatment success'],['Support','Address barriers and toxicity']],[TX,CD],style='clinical_scenario')
q('A previously treated patient has persistent cough and a trace-positive molecular TB result. Which principle is most appropriate?', 'Interpret the result with symptoms, timing, culture and other evidence because residual DNA can complicate post-treatment interpretation',[
 ('Any positive molecular result proves viable recurrent TB','Molecular detection can persist without viable organisms.'),('Prior TB makes recurrent TB impossible','Relapse and reinfection can occur.'),('A negative smear excludes recurrence','Smear sensitivity is insufficient for exclusion.')],
 'Detection of nucleic acid is not identical to demonstration of viability', '**Recent treatment history changes the interpretation of low-level molecular detection.**',['Assess recurrence risk and the clinical trajectory.','Culture and susceptibility testing can provide important additional evidence.'], '**Avoid both automatic retreatment and automatic dismissal.**',['Structural lung disease and other infections may explain symptoms.','Use the current diagnostic algorithm and expert assessment for discordant findings.'],[['Molecular result','DNA detection'],['Culture','Evidence relevant to viable organisms'],['Clinical context','Distinguishes competing explanations']],[DX,PT],style='clinical_scenario')
q('A patient completes microbiologically successful TB treatment but remains breathless. What is the best next assessment strategy?', 'Evaluate for post-TB lung disease and other causes rather than assuming ongoing active infection',[
 ('Restart the same regimen solely for dyspnea','Persistent symptoms alone do not establish recurrent TB.'),('Declare normal lung health because treatment succeeded','Infection cure does not guarantee reversal of structural damage.'),('Use IGRA conversion to negativity as the only recovery endpoint','IGRA is not a functional recovery test.')],
 'Microbiological cure and pulmonary recovery are different outcomes', '**Post-TB disease can involve airways, parenchyma, pleura and pulmonary vessels.**',['Obstruction, restriction or mixed physiology may occur.','Assess recurrent infection when clinical features warrant it.'], '**Measure the residual burden.**',['Symptoms, oxygenation, spirometry and imaging guide further evaluation.','Exercise assessment and rehabilitation planning may identify treatable limitations.'],[['Infection outcome','Microbiological treatment success'],['Residual disease','Structural and functional impairment'],['Assessment','Clinical, physiological and imaging evaluation']],[PT],style='clinical_scenario')
q('Which spirometric pattern can occur after pulmonary tuberculosis?', 'Obstructive, restrictive or mixed abnormalities, depending on the residual damage',[
 ('Only a restrictive pattern','Post-TB airway disease can cause obstruction.'),('Only fully reversible obstruction','Fixed obstruction and other patterns occur.'),('Necessarily normal spirometry after culture conversion','Microbiological response does not prove normal physiology.')],
 'Post-TB physiology is heterogeneous', '**Airway destruction and scarring can produce different functional patterns.**',['Use quality-assured pre- and post-bronchodilator testing where appropriate.','Low FVC alone does not confirm restriction without lung-volume assessment.'], '**Link physiology to symptoms and structural findings.**',['Assess hypoxemia and exercise limitation.','Management should target the demonstrated phenotype rather than a single post-TB label.'],[['Airways','Obstruction may occur'],['Parenchymal / pleural damage','Restrictive effects may occur'],['Combined injury','Mixed defects are possible']],[PT])
q('A patient with prior TB has daily purulent sputum, recurrent infections and CT-dilated non-tapering bronchi. Which residual disorder is most likely?', 'Post-TB bronchiectasis',[
 ('Latent infection alone','Latent infection does not explain structural bronchial dilatation.'),('Simple deconditioning alone','It does not account for chronic purulent sputum and CT abnormalities.'),('An isolated pleural effusion','This does not explain the airway findings.')],
 'Damaged airways can sustain a cycle of infection and impaired clearance', '**Bronchiectasis is a recognized post-TB complication.**',['Assess sputum microbiology during relevant clinical episodes.','Distinguish chronic colonization from an acute exacerbation.'], '**Provide airway-clearance and phenotype-directed care.**',['Review vaccination, exercise and nutrition.','Check for recurrent TB or nontuberculous mycobacteria when indicated before long-term antimicrobial strategies.'],[['Structural clue','Dilated non-tapering bronchi'],['Symptoms','Chronic sputum and recurrent infections'],['Care','Clearance, microbiology and prevention']],[PT],style='clinical_scenario')
q('Years after treated TB, a patient develops recurrent hemoptysis. Which assessment is most appropriate?', 'Evaluate bleeding severity and investigate causes including bronchiectasis, recurrent TB, chronic fungal disease and vascular lesions',[
 ('Assume every episode proves TB relapse','Several post-TB causes can bleed.'),('Ignore the episode because the old infection was cured','Hemoptysis may be dangerous even without active TB.'),('Prescribe preventive isoniazid as definitive bleeding treatment','This does not manage the source or immediate risk.')],
 'Post-TB hemoptysis has a broad differential', '**Immediate priorities are airway, oxygenation and hemodynamic assessment.**',['Bronchial-systemic vessels are common bleeding sources.','A pulmonary artery pseudoaneurysm is an important alternative in the appropriate setting.'], '**Select CT angiography, bronchoscopy and embolization according to severity and location.**',['Investigate infection and malignancy when relevant.','Do not delay stabilization while assigning an etiological label.'],[['Immediate','Stabilize and quantify clinical severity'],['Causes','Airway, infectious, fungal, vascular or neoplastic'],['Definitive care','Source-directed intervention']],[PT],style='clinical_scenario')
q('What is the role of pulmonary rehabilitation in a patient with stable post-TB lung impairment and exercise limitation?', 'It can address dyspnea, functional limitation and self-management after appropriate assessment',[
 ('It eradicates viable M. tuberculosis without drugs','Rehabilitation is not antimicrobial treatment.'),('It is contraindicated in every person with residual radiographic scarring','Stable scarring alone is not a universal contraindication.'),('It guarantees reversal of all fibrosis','Rehabilitation improves function without necessarily reversing structural damage.')],
 'Rehabilitation targets disability after infection treatment', '**Exercise training and education can improve functional recovery.**',['Assess cardiopulmonary stability and exertional oxygenation.','Nutrition and psychosocial needs can affect participation.'], '**Individualize the programme to the residual phenotype.**',['Airway clearance may be relevant with sputum-producing bronchiectasis.','Reassess goals and functional measures over time.'],[['Target','Symptoms and activity limitation'],['Components','Exercise, education and selected supportive care'],['Limit','Does not guarantee anatomical reversal']],[PT])
q('What is the best approach to infectiousness in a patient with suspected pulmonary TB awaiting results?', 'Use airborne infection-control measures appropriate to the setting while diagnostic evaluation proceeds',[
 ('Standard hand hygiene alone is sufficient for all settings','Pulmonary TB can spread through airborne particles.'),('A negative IGRA permits immediate removal of respiratory precautions','IGRA cannot exclude active infectious disease.'),('Wait for culture confirmation before any infection-control action','Culture delay can permit avoidable exposure.')],
 'Transmission prevention begins with suspicion', '**Use early recognition, separation, ventilation and appropriate respiratory protection.**',['Apply local airborne-precaution protocols.','Educate the patient about respiratory hygiene and treatment.'], '**Use clinical and microbiological criteria for subsequent decisions.**',['Infectiousness is not determined by an immune test.','Coordinate contact assessment and public health reporting under the national programme.'],[['Start','At appropriate clinical suspicion'],['Protection','Airborne measures and ventilation'],['Review','Local clinical and microbiological criteria']],[LT,TX],style='clinical_scenario')
q('Which statement best reflects the WHO 2025 approach to MDR/RR-TB treatment options?', 'Validated shorter all-oral regimens are available for eligible patients, with selection based on resistance, prior exposure and patient factors',[
 ('Every patient must receive an injectable-based 24-month regimen','That is not the current universal approach.'),('All six-month regimens are interchangeable regardless of resistance','Their components and eligibility differ.'),('Newer drugs eliminate the need for toxicity monitoring','Important hematologic, neurologic, cardiac and other adverse effects remain.')],
 'Shorter resistant-TB treatment is a structured regimen decision', '**WHO guidance includes six-month all-oral options, including BPaLM and a newer BDLLfxC option for appropriate patients.**',['Do not assume identical eligibility across regimens.','National implementation and susceptibility capacity matter.'], '**Combine regimen selection with active safety and adherence support.**',['Assess previous exposure to component drugs.','Monitor drug-specific toxicity and microbiological response.'],[['Current principle','Shorter validated all-oral options'],['Selection','Resistance and eligibility'],['Follow-up','Safety, support and response']],[TX])

if __name__=='__main__':finalize('Respiratory system',5,'Tuberculosis and Post-TB Lung Disease','resp-tb',rows,24)
